4	export type RunOutcome = 'pass' | 'fail' | 'unknown';
5	
6	export interface ToolRun {
7	  callEntryId: string;
8	  resultEntryId: string | null;
9	  index: number;
10	  command: string;
11	  cls: CommandClass;
12	  outcome: RunOutcome;
13	}
