6	export interface ScorecardInput {
7	  date: string;
8	  mutation: { cases: MutationCase[]; recognised: number; unknown: number; flipRate: number };
9	  grounding: { fabricated: number; rejected: number; genuine: number; accepted: number };
10	  skipped: { repo: string; reason: string }[];
11	  tails?: TailCount[];
12	}
