14	function recognitionRate(recognised: number, unknown: number): number {
15	  const total = recognised + unknown;
16	  return total === 0 ? 0 : recognised / total;
17	}
18	
19	// Collapses line breaks and control characters (which would split a table row or list item
20	// across lines) and escapes the characters that would otherwise break a Markdown table cell or
21	// inline code span: a literal `|` adds a column, a backtick closes the span early.
22	function sanitizeCell(text: string): string {
23	  return text
24	    .replace(/[\r\n]+/g, ' ')
25	    .replace(/[\u0000-\u001f]/g, '')
26	    .replace(/\\/g, '\\\\') // escape pre-existing backslashes first, so a "\|" in the source can't
27	    .replace(/\|/g, '\\|') // absorb the pipe's own escaping backslash and leave the pipe bare
28	    .replace(/`/g, "'");
29	}
30	
31	// Error messages from @dailies/ingest (e.g. NoCheckpointsError) embed the repo URL verbatim.
32	// Scrub it wherever it appears, not just in the dedicated `repo` field.
33	function scrubRepo(text: string, repo: string): string {
34	  return repo ? text.split(repo).join(repoKey(repo)) : text;
35	}
36	
37	// Known enough, and inherently argument-free as bare program names, to publish as-is.
38	const KNOWN_PROGRAMS = new Set([
39	  'cd', 'ls', 'git', 'go', 'cargo', 'make', 'node', 'npm', 'pnpm', 'yarn', 'bun', 'npx', 'tsx',
40	  'python', 'python3', 'perl', 'ruby', 'tsc', 'eslint', 'biome', 'ruff', 'flake8', 'mypy',
41	  'pyright', 'pytest', 'jest', 'vitest', 'mocha', 'playwright', 'rspec', 'phpunit', 'dotnet',
42	  'bash', 'sh', 'echo', 'grep', 'sed', 'awk', 'curl', 'docker', 'mise',
43	]);
44	
45	// A recorded command is arbitrary agent-authored shell text: it can carry a bare
46	// "github.com/owner/repo" module path (no scheme, so scrubRepo's exact-URL match misses it), an
47	// operator's local filesystem path with their username in it (seen verbatim in real data — a
48	// recorded `cd /Users/<name>/...`), or a leading `VAR=value` shell assignment whose value could
49	// be anything, including a secret under a name redact() doesn't recognise. There is no bounded
50	// set of patterns to scrub for all of that, so the command is never published raw: only its
51	// deterministic class, plus a program name taken strictly from a fixed allowlist (an unknown
52	// binary becomes "other"), survives.
53	export function safeCommand(command: string): string {
54	  const withoutAssignments = command.trim().replace(/^(?:[A-Za-z_][A-Za-z0-9_]*=\S*\s+)+/, '');
55	  const first = withoutAssignments.split(/\s+/)[0] ?? '';
56	  const base = first.split('/').pop() || first;
57	  const programName = KNOWN_PROGRAMS.has(base) ? base : 'other';
58	  return `${classifyCommand(command)}:${programName}`;
59	}
60	
61	/** Renders the mutation/grounding totals and every non-flipping case as Markdown, identifying
62	 * repositories only by repoKey so a result never names one. */
63	export function buildScorecard(input: ScorecardInput): string {
64	  const { date, mutation, grounding, skipped, tails = [] } = input;
65	  const rate = recognitionRate(mutation.recognised, mutation.unknown);
66	  const nonFlipping = mutation.cases.filter((c) => !c.flipped);
67	
68	  const lines: string[] = [];
69	  lines.push(`# Dailies evaluation scorecard — ${date}`, '');
70	
71	  lines.push('## Mutation benchmark');
72	  lines.push(`- recognised: ${mutation.recognised}`);
73	  lines.push(`- unknown: ${mutation.unknown}`);
74	  lines.push(`- recognition rate: ${rate.toFixed(3)}`);
75	  lines.push(`- cases: ${mutation.cases.length}`);
76	  lines.push(`- flip rate: ${mutation.flipRate.toFixed(3)}`);
77	  lines.push('');
78	
79	  lines.push('### Non-flipping cases');
80	  if (nonFlipping.length === 0) {
81	    lines.push('None.');
82	  } else {
83	    lines.push('| repo | session | command | original | before | after |');
84	    lines.push('|---|---|---|---|---|---|');
85	    for (const c of nonFlipping) {
86	      const command = sanitizeCell(scrubRepo(safeCommand(c.command), c.repo));
87	      const sessionId = sanitizeCell(c.sessionId);
88	      lines.push(`| ${repoKey(c.repo)} | ${sessionId} | ${command} | ${c.original} | ${c.verdictBefore} | ${c.verdictAfter} |`);
89	    }
90	  }
91	  lines.push('');
92	
93	  lines.push('## Grounding benchmark');
94	  lines.push(`- fabricated: ${grounding.fabricated}, rejected: ${grounding.rejected}`);
95	  lines.push(`- genuine: ${grounding.genuine}, accepted: ${grounding.accepted}`);
96	  lines.push('');
97	
98	  lines.push('## Skipped repositories');
99	  if (skipped.length === 0) {
100	    lines.push('None.');
101	  } else {
102	    for (const s of skipped) lines.push(`- ${repoKey(s.repo)}: ${sanitizeCell(scrubRepo(s.reason, s.repo))}`);
103	  }
104	
105	  if (tails.length > 0) {
106	    lines.push('');
107	    lines.push('## Unrecognised output tails');
108	    tails.forEach((t, i) => lines.push(`${i + 1}. (${t.count}x) \`${sanitizeCell(t.tail)}\``));
109	  }
110	
111	  return `${lines.join('\n')}\n`;
112	}
